{
  "id": "V024",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "휴직 신청 문의 대응 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "조건·서류 설명과 판단이 어려운 문의의 인사팀 이관이 포함됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "휴직 신청의 적용 조건, 제출 서류 및 문의가 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "직원의 질문과 현재 게시된 사내 규정이 보존됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "조건·서류 설명 및 인사 담당자에게 넘길 문의가 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "게시된 규정을 근거로 하고, 답을 확정하기 어려운 문의만 이관하는 조건이 보존됨."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "승인이나 시스템 변경 등 지원되지 않는 기능을 추가하지 않음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "직원과 인사 담당자의 역할 구분이 보존됨."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "휴직 신청의 승인이나 인사시스템 정보 변경은 포함하지 않습니다.",
      "view_quote": "",
      "reason": "승인 및 인사시스템 정보 변경을 제외한다는 제약이 모든 뷰에서 빠짐."
    }
  ],
  "permission_interpretation": "인사 담당자에게 넘기는 것은 담당자에게 검토를 맡기는 의미이며, 담당자가 매번 승인하거나 시스템을 변경한다는 뜻은 아님."
}
